WITH matched_keys AS (SELECT category FROM products INTERSECT SELECT category FROM products WHERE price >= 690), verified AS (SELECT s.* FROM products s INNER JOIN matched_keys k ON s.category = k.category), cleaned AS (SELECT *, COALESCE(price, 0) AS price_filled, COALESCE(brand, 'DIRECT') AS brand_filled FROM verified WHERE launch_date >= DATE '2023-04-19'), joined AS (SELECT a.*, p.rating FROM cleaned a LEFT JOIN suppliers p ON a.supplier_id = p.id WHERE p.rating >= 3.9), not_flagged AS (SELECT s.* FROM joined s WHERE EXISTS (SELECT 1 FROM inventory x WHERE x.product_id = s.id AND x.last_restock < s.launch_date)), joined_products AS (SELECT src.category, src.brand, src.price, src.cost, src.stock_qty, src.tags, src.supplier_id, src.brand_filled, src.rating, d.country FROM not_flagged src LEFT JOIN suppliers d ON src.supplier_id = d.id), joined_products_2 AS (SELECT a.category, a.price, a.stock_qty, a.supplier_id, a.rating, s.supplier_name, s.country AS supplier_country FROM joined_products a LEFT JOIN suppliers s ON a.supplier_id <=> s.id), base AS (SELECT category, price, stock_qty, supplier_id, supplier_name, supplier_country, CONCAT(category, '/', supplier_name) AS category_supplier_name FROM joined_products_2 WHERE supplier_id IS NOT NULL), wide AS (SELECT * FROM (SELECT supplier_id, category, supplier_country, price FROM base) src PIVOT (AVG(price) FOR supplier_country IN ('UK', 'SG', 'US'))) SELECT s.supplier_id, s.category, s.UK, s.US, (SELECT MIN(x.stock_qty) FROM products x WHERE x.supplier_id = s.supplier_id) AS min_product_stock_qty FROM wide s;
